h=0.01
def lag(u,T):
    al=1-np.exp(-h/T)
    return lfilter([al],[1,-(1-al)],u)  # x_k+1 = (1-al)x_k + al u_k  (x0=0 approx)
def simQ(p,d):
    a,b,c,e,T1,T2=p
    V=d.voltage_pu.values; S=d.voltage_setpoint_pu.values
    Q0=d.reactive_power_pu.values[0]; V0=V[0]
    x1=lag(V-V0,T1); x2=lag(V-V0,T2)
    return Q0+a*(S-V0)+b*(V-V0)+c*x1+e*x2
def resQ(p,fs): return np.concatenate([D[f].reactive_power_pu.values-simQ(p,D[f]) for f in fs])
